#include <bits/stdc++.h>
using namespace std;

class Solution {
    int depth(TreeNode* node) {
        if (!node) return 0;
        if (node->left && node->left->right == node) return 0;
        return 1 + max(depth(node->left), depth(node->right));
    }
public:
    int heightOfTree(TreeNode* root) {
        return depth(root);
    }
};
